/// <summary>
/// Displays project Id
/// </summary>
/// <returns>Building project id</returns>
display KCS_KBVBuildingProjectID dispKCS_KBVBuildingProjectID()
{
    KCS_KBVBuildingProjectID lKCS_KBVBuildingProjectID;

    KCS_KBVBuildingProjectTable lKCS_KBVBuildingProjectTable = KCS_KBVBuildingProjectTable::findByRecId(this.RefRecId_KCS_KBVBuildingProject);
    lKCS_KBVBuildingProjectID = lKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;

    return lKCS_KBVBuildingProjectID;
}

/// <summary>
/// Finds record    
/// </summary>
/// <param name = "_inventTable">_inventTable</param>
/// <param name = "_update">true or false</param>
/// <returns>Record</returns>
static public NDXMultipleS_KBV_BuildingProject find(InventTable _inventTable, boolean _update = false)
{
    NDXMultipleS_KBV_BuildingProject lNDXMultipleS_KBV_BuildingProject;

    if(_inventTable)
    {
        lNDXMultipleS_KBV_BuildingProject.selectForUpdate(_update);

        select lNDXMultipleS_KBV_BuildingProject
            where lNDXMultipleS_KBV_BuildingProject.RefRecId_InventTable == _inventTable.RecId;
    }

    return lNDXMultipleS_KBV_BuildingProject;
}

/// <summary>
/// Checks if check is available
/// </summary>
/// <param name = "_inventTable">_inventTable</param>
/// <returns>true or false</returns>
static public boolean hasValidityCheck(InventTable _inventTable)
{
    return NDXMultipleS_KBV_BuildingProject::find(_inventTable).RecId > 0;
}

/// <summary>
/// Return all validation BV Ids for the item as string
/// </summary>
/// <param name = "_itemRecId">_itemRecId</param>
/// <returns>String of BV Ids</returns>
static str Range2String(RecID _itemRecId)
{
    #define.Comma(' ,')

    NDXMultipleS_KBV_BuildingProject       nDX_MultipleS_KBV_BuildingProject;
    KCS_KBVBuildingProjectTable lKCS_KBVBuildingProjectTable;
    str    range2String;
    boolean             lFirst = true;
    ;
    while select nDX_MultipleS_KBV_BuildingProject
        where nDX_MultipleS_KBV_BuildingProject.RefRecId_InventTable == _itemRecId
        join lKCS_KBVBuildingProjectTable
            where lKCS_KBVBuildingProjectTable.RecId == nDX_MultipleS_KBV_BuildingProject.RefRecId_KCS_KBVBuildingProject
    {
        if (!lFirst)
        {
            range2String += #Comma;
        }
        else
        {
            lFirst = false;
        }

        range2String += lKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
    }
    return range2String;
}

public void insert()
{
    NDXMultipleS_KBV_BuildingProject orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void update()
{
    NDXMultipleS_KBV_BuildingProject orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void delete()
{
    NDXMultipleS_KBV_BuildingProject orig = this.orig();
    super();
    this.writeLog(orig, null);
}

/// <summary>
/// Writes log change
/// </summary>
/// <param name = "_orig">record before</param>
/// <param name = "_current">record after</param>
private void writeLog(NDXMultipleS_KBV_BuildingProject _orig, NDXMultipleS_KBV_BuildingProject _current)
{
    NDXMultipleS_Log   multipleS_Log;

    if(!_current)
    {
        multipleS_Log.RefRecIdInventTable = _orig.RefRecId_InventTable;
    }
    else
    {
        multipleS_Log.RefRecIdInventTable = _current.RefRecId_InventTable;
    }

    if (_orig.RefRecId_KCS_KBVBuildingProject != _current.RefRecId_KCS_KBVBuildingProject)
    {
        multipleS_Log.ValidityCheckType = NDXValidityCheckType::BV;

        multipleS_Log.RangeValue        =  KCS_KBVBuildingProjectTable::findByRecId(_current.RefRecId_KCS_KBVBuildingProject).KCS_KBVBuildingProjectID;

        if (!_orig.RefRecId_KCS_KBVBuildingProject)            // Neuanlage
        {
            multipleS_Log.ChangeType        = NDXChangeType::New;
        }
        else if (!_current.RefRecId_KCS_KBVBuildingProject) // Löschung
        {
            multipleS_Log.RangeValue        = KCS_KBVBuildingProjectTable::findByRecId(_orig.RefRecId_KCS_KBVBuildingProject).KCS_KBVBuildingProjectID;
            multipleS_Log.ChangeType        = NDXChangeType::Delete;
        }
        else                                // Änderung
        {
            multipleS_Log.RangeValue        += strFmt("@ApplicationFoundation:DocuDeletedRefCaptionGeneratorFromLabel", KCS_KBVBuildingProjectTable::findByRecId(_orig.RefRecId_KCS_KBVBuildingProject).KCS_KBVBuildingProjectID);
            multipleS_Log.ChangeType        = NDXChangeType::Update;
        }
        multipleS_Log.insert();
    }

}
